def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    my_def = sum(1 for a in me if a == 'D')
    last_opp = opp[-1]

    # Last round: always defect
    if n >= 99:
        return 'D'

    # Test phase: if no one has defected yet, test at round 21
    if opp_def == 0 and my_def == 0:
        if n >= 20:
            return 'D'
        return 'C'

    # If we tested and opponent didn't retaliate on the next round, they are always C
    if opp_def == 0 and my_def == 1 and n == 21:
        return 'C'

    # Opponent still hasn't defected: exploit by defecting every round
    if opp_def == 0 and my_def >= 1:
        return 'D'

    # Regular mode: Tit-for-Tat with forgiveness
    if last_opp == 'D':
        if opp_def / n < 0.2 and rng.random() < 0.3:
            return 'C'
        return 'D'
    else:
        if opp_def / n < 0.1 and rng.random() < 0.05:
            return 'D'
        return 'C'
